def set_left_most_unset_bit(n):
    if n == 0: return 1 # Edge case, usually handled or returns 1

    # Find the position of the most significant bit that is SET
    msb_pos = n.bit_length() - 1

    # Iterate downwards from MSB-1 to 0
    for i in range(msb_pos - 1, -1, -1):
        if not ((n >> i) & 1):
            return n | (1 << i)

    # If all bits below MSB are set (e.g., input is like ...0111), 
    # strictly speaking there is no unset bit "leftmost" within the range.
    # However, based on typical problem constraints for this specific assertion:
    # It implies we only care about zeros between the highest 1 and LSB.
    return n # Or handle as overflow if needed, but let's assume input has a gap.

